### Internal Implementation (from compiled `dialogService-Cr3DyAja.js`)

The decompiled core logic (reformatted for readability):

```javascript
graphToPrompt = async (graph, options = {}) => {
  const { sortNodes = false } = options;

  // 1. Apply virtual nodes (primitives link their values into the graph)
  for (let node of graph.computeExecutionOrder(false)) {
    const innerNodes = node.getInnerNodes ? node.getInnerNodes(new Map) : [node];
    for (let n of innerNodes) {
      if (n.isVirtualNode) n.applyToGraph?.();
    }
  }

  // 2. Serialize to workflow (UI) format
  const r = graph.serialize({ sortNodes });
  // Strip localized names
  for (let node of r.nodes) {
    for (let input of node.inputs ?? []) delete input.localized_name;
    for (let output of node.outputs ?? []) delete output.localized_name;
  }
  compressWidgetInputSlots(r);
  r.extra ??= {};
  r.extra.frontendVersion = `1.38.13`;

  // 3. Build execution order map (handles group nodes)
  const nodeMap = new Map();
  for (let node of graph.computeExecutionOrder(false)) {
    const dto = isGroupNode(node)
      ? new ExecutableGroupNodeDTO(node, [], nodeMap)
      : new Ni(node, [], nodeMap);
    for (let n of dto.getInnerNodes()) nodeMap.set(n.id, n);
    nodeMap.set(dto.id, dto);
  }

  // 4. Build API output format
  const output = {};
  for (let node of nodeMap.values()) {
    if (node.isVirtualNode || node.mode === NEVER || node.mode === BYPASS) continue;

    const inputs = {};

    // Serialize widget values
    for (let [idx, widget] of node.widgets.entries()) {
      if (!widget.name || widget.options?.serialize === false) continue;
      const value = widget.serializeValue
        ? await widget.serializeValue(node, idx)
        : widget.value;
      inputs[widget.name] = Array.isArray(value) ? { __value__: value } : value;
    }

    // Serialize connections
    for (let [idx, input] of node.inputs.entries()) {
      const resolved = node.resolveInput(idx);
      if (resolved) {
        if (resolved.widgetInfo) {
          const { value } = resolved.widgetInfo;
          inputs[input.name] = Array.isArray(value) ? { __value__: value } : value;
        } else {
          inputs[input.name] = [String(resolved.origin_id), parseInt(resolved.origin_slot)];
        }
      }
    }

    output[String(node.id)] = {
      inputs,
      class_type: node.comfyClass,
      _meta: { title: node.title }
    };
  }

  // 5. Clean up dangling connections (links to nodes not in output)
  for (let { inputs } of Object.values(output)) {
    for (let [key, val] of Object.entries(inputs)) {
      if (Array.isArray(val) && val.length === 2 && !output[val[0]]) {
        delete inputs[key];
      }
    }
  }

  return { workflow: r, output };
};
```

